import java.util.Map;

public class WordCounterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        String[] words = {"Apple", "apple", "BANANA", "banana", "Cherry", "APPLE"};
        Map<String, Integer> counts = WordCounter.wordCounts(words);

        check("count of apple (case-insensitive)", 3, counts.get("apple"));
        check("count of banana", 2, counts.get("banana"));
        check("count of cherry", 1, counts.get("cherry"));
        check("map has exactly 3 distinct words", 3, counts.size());
        check("keys are lowercased, so get(\"Apple\") is null", null, counts.get("Apple"));

        Map<String, Integer> single = WordCounter.wordCounts(new String[]{"Hi"});
        check("single word", 1, single.get("hi"));

        Map<String, Integer> empty = WordCounter.wordCounts(new String[]{});
        check("empty array gives empty map", 0, empty.size());

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

